  function mcq(stem, options, correct, reasons, equations) {
    const prompt = [...stem];
    options.forEach((option,i) => prompt.push('  '+optionNames[i]+' ',option));
    return {prompt,reasons,equations,answer:[optionNames[correct]+' ',options[correct]]};
  }
